 questions=$assessment$[{"id":"ep-01","prompt":"Jaką książkę najchętniej przeczytasz dla przyjemności?","options":[{"text":"Książkę z dużą liczbą ilustracji","style":"visual"},{"text":"Książkę z dużą ilością tekstu","style":"auditory"},{"text":"Książkę z wykreślankami lub krzyżówkami","style":"kinesthetic"}]},{"id":"ep-02","prompt":"Co najczęściej robisz, gdy nie masz pewności, jak zapisać jakieś słowo?","options":[{"text":"Zapisuję je, żeby sprawdzić, czy wygląda poprawnie","style":"visual"},{"text":"Literuję je na głos, żeby sprawdzić, czy brzmi poprawnie","style":"auditory"},{"text":"Kreślę litery palcem w powietrzu","style":"kinesthetic"}]},{"id":"ep-03","prompt":"Kupujesz ubrania i czekasz w kolejce do kasy. Co najprawdopodobniej robisz podczas czekania?","options":[{"text":"Oglądam inne ubrania na wieszakach","style":"visual"},{"text":"Rozmawiam z osobą stojącą obok mnie w kolejce","style":"auditory"},{"text":"Wiercę się lub przestępuję z nogi na nogę","style":"kinesthetic"}]},{"id":"ep-04","prompt":"Co robisz najpierw, gdy widzisz słowo „kot”?","options":[{"text":"Wyobrażam sobie kota","style":"visual"},{"text":"Wypowiadam w myślach słowo „kot”","style":"auditory"},{"text":"Myślę o kontakcie z kotem — głaskaniu go lub słuchaniu jego mruczenia","style":"kinesthetic"}]},{"id":"ep-05","prompt":"Jaki sposób przygotowania do sprawdzianu najbardziej Ci odpowiada?","options":[{"text":"Czytam podręcznik lub notatki oraz przeglądam ilustracje i wykresy","style":"visual"},{"text":"Ktoś zadaje mi pytania, na które odpowiadam na głos","style":"auditory"},{"text":"Przygotowuję fiszki, które mogę potem przeglądać","style":"kinesthetic"}]},{"id":"ep-06","prompt":"Jak najlepiej uczysz się, jak coś działa, na przykład komputer lub gra wideo?","options":[{"text":"Proszę kogoś, żeby mi to pokazał","style":"visual"},{"text":"Czytam o tym lub słucham czyjegoś wyjaśnienia","style":"auditory"},{"text":"Samodzielnie próbuję zrozumieć, jak to działa","style":"kinesthetic"}]},{"id":"ep-07","prompt":"Co najprawdopodobniej zapamiętasz następnego dnia po szkolnej zabawie tanecznej?","options":[{"text":"Twarze osób, które tam były","style":"visual"},{"text":"Muzykę, która była grana","style":"auditory"},{"text":"Wykonywane przeze mnie kroki taneczne i jedzenie, którego próbowałem lub próbowałam","style":"kinesthetic"}]},{"id":"ep-08","prompt":"Co najbardziej Cię rozprasza, gdy próbujesz się uczyć?","options":[{"text":"Przechodzący obok ludzie","style":"visual"},{"text":"Głośne dźwięki","style":"auditory"},{"text":"Niewygodne krzesło","style":"kinesthetic"}]},{"id":"ep-09","prompt":"Co najczęściej robisz, kiedy się złościsz?","options":[{"text":"Pokazuję złość wyrazem twarzy","style":"visual"},{"text":"Podnoszę głos i krzyczę","style":"auditory"},{"text":"Trzaskam drzwiami","style":"kinesthetic"}]},{"id":"ep-10","prompt":"Co najczęściej robisz, kiedy się cieszysz?","options":[{"text":"Uśmiecham się od ucha do ucha","style":"visual"},{"text":"Mówię bez przerwy","style":"auditory"},{"text":"Rozpiera mnie energia i trudno mi usiedzieć w miejscu","style":"kinesthetic"}]},{"id":"ep-11","prompt":"Jak odnajdujesz drogę w nowym miejscu?","options":[{"text":"Szukam mapy lub planu pokazującego, gdzie co się znajduje","style":"visual"},{"text":"Pytam kogoś o drogę","style":"auditory"},{"text":"Zaczynam chodzić po okolicy, aż znajdę to, czego szukam","style":"kinesthetic"}]},{"id":"ep-12","prompt":"Które z tych trzech zajęć lubisz najbardziej?","options":[{"text":"Zajęcia plastyczne","style":"visual"},{"text":"Zajęcia muzyczne","style":"auditory"},{"text":"Wychowanie fizyczne","style":"kinesthetic"}]},{"id":"ep-13","prompt":"Co najczęściej robisz, gdy słyszysz piosenkę w radiu?","options":[{"text":"Wyobrażam sobie jej teledysk","style":"visual"},{"text":"Śpiewam lub nucę razem z muzyką","style":"auditory"},{"text":"Zaczynam tańczyć lub wystukiwać rytm stopą","style":"kinesthetic"}]},{"id":"ep-14","prompt":"Co najbardziej rozprasza Cię podczas zajęć?","options":[{"text":"Zbyt jasne lub zbyt słabe oświetlenie","style":"visual"},{"text":"Dźwięki z korytarza lub spoza budynku, na przykład ruch uliczny albo koszenie trawy","style":"auditory"},{"text":"Zbyt wysoka lub zbyt niska temperatura","style":"kinesthetic"}]},{"id":"ep-15","prompt":"Co lubisz robić, żeby się odprężyć?","options":[{"text":"Czytać","style":"visual"},{"text":"Słuchać muzyki","style":"auditory"},{"text":"Ruszam się: spaceruję, biegam lub uprawiam sport","style":"kinesthetic"}]},{"id":"ep-16","prompt":"Jaki sposób najlepiej pomaga Ci zapamiętać numer telefonu znajomej osoby?","options":[{"text":"Wyobrażam sobie cyfry na telefonie tak, jak podczas wybierania numeru","style":"visual"},{"text":"Wielokrotnie powtarzam numer na głos","style":"auditory"},{"text":"Zapisuję go lub dodaję do kontaktów w telefonie","style":"kinesthetic"}]},{"id":"ep-17","prompt":"Jeśli wygrasz w grze, którą z tych trzech nagród wybierzesz?","options":[{"text":"Plakat na ścianę","style":"visual"},{"text":"Kartę podarunkową do serwisu muzycznego","style":"auditory"},{"text":"Jakąś grę lub piłkę, na przykład do futbolu amerykańskiego albo piłki nożnej","style":"kinesthetic"}]},{"id":"ep-18","prompt":"Dokąd najchętniej wybierzesz się z grupą znajomych?","options":[{"text":"Do kina","style":"visual"},{"text":"Na koncert","style":"auditory"},{"text":"Do parku rozrywki","style":"kinesthetic"}]},{"id":"ep-19","prompt":"Co najczęściej zapamiętujesz o nowo poznanych osobach?","options":[{"text":"Ich twarz, ale nie imię","style":"visual"},{"text":"Ich imię, ale nie twarz","style":"auditory"},{"text":"To, o czym rozmawialiśmy","style":"kinesthetic"}]},{"id":"ep-20","prompt":"Jak najczęściej wyjaśniasz komuś drogę do swojego domu?","options":[{"text":"Opisuję budynki i charakterystyczne miejsca mijane po drodze","style":"visual"},{"text":"Podaję nazwy dróg lub ulic, którymi trzeba się poruszać","style":"auditory"},{"text":"Mówię: „Chodź za mną — łatwiej będzie, jeśli po prostu pokażę Ci drogę”","style":"kinesthetic"}]}]$assessment$::jsonb where id;
